{"implementation":"import math

def solve(case):
    if not isinstance(case, dict):
        raise ValueError('case must be an object')
    for key in ('nodes', 'core_distance', 'distances'):
        if key not in case:
            raise ValueError('missing required field: ' + key)

    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    if not isinstance(nodes, list) or not isinstance(core, dict) or not isinstance(distances, list):
        raise ValueError('invalid input field type')
    if any(not isinstance(node, str) for node in nodes) or len(set(nodes)) != len(nodes):
        raise ValueError('nodes must be unique strings')
    node_set = set(nodes)
    if set(core) != node_set:
        raise ValueError('core_distance keys must match nodes')

    def number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)

    for node in nodes:
        if not number(core[node]):
            raise ValueError('invalid core distance')

    edges = []
    seen = set()
    for item in distances:
        if not isinstance(item, (list, tuple)) or len(item) != 3:
            raise ValueError('invalid distance entry')
        left, right, distance = item
        if not isinstance(left, str) or not isinstance(right, str) or left not in node_set or right not in node_set or left == right:
            raise ValueError('invalid distance endpoints')
        if not number(distance):
            raise ValueError('invalid distance')
        a, b = sorted((left, right))
        pair = (a, b)
        if pair in seen:
            raise ValueError('duplicate undirected distance edge')
        seen.add(pair)
        weight = max(core[left], core[right], distance)
        edges.append((weight, a, b))

    edges.sort(key=lambda edge: (edge[0], edge[1], edge[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root == right_root:
            return False
        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root
        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1
        return True

    mst_edges = []
    total_weight = 0
    for weight, left, right in edges:
        if union(left, right):
            mst_edges.append([left, right, weight])
            total_weight += weight
            if len(mst_edges) == len(nodes) - 1:
                break

    if len(mst_edges) != max(0, len(nodes) - 1):
        raise ValueError('distance graph is disconnected')
    return {'mst_edges': mst_edges, 'total_weight': total_weight}
